/*
 * A057313  Coordination sequence T2 for Zeolite Code SAS.
 * https://oeis.org/A057313
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   Generated by the rational generating function A(x) = (1 + x) *
 *            (1 + x + 2*x^2 + 4*x^3 + 6*x^4 + 5*x^5 + 6*x^6 + 5*x^7 + 6*x^8 +
 *            4*x^9 + 2*x^10 + x^11 + x^12) / ((1 - x)^3 * (1 - x + x^2) * (1
 *            + x + x^2 + x^3 + x^4)^2). The coefficients satisfy the
 *            constant–coefficient linear recurrence (order 13)...
 * Range:     u8 n <= 12, u16 n <= 193, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>

static const seq_t init[14] = {
    1, 4, 9, 17, 30, 48, 68, 87, 109, 142, 184, 224, 255, 287
};

static const int coeff[14] = {
    1,  /* d0 (unused) */
    -2, /* d1 */
    2,  /* d2 */
    -1, /* d3 */
    0,  /* d4 */
    -2, /* d5 */
    4,  /* d6 */
    -4, /* d7 */
    2,  /* d8 */
    0,  /* d9 */
    1,  /* d10 */
    -2, /* d11 */
    2,  /* d12 */
    -1  /* d13 */
};

seq_t a(idx_t n)
{
    if (n < 14) {
        return init[(size_t)n];
    }

    seq_t buf[14];
    for (size_t i = 0; i < 14; ++i) {
        buf[i] = init[i];
    }

    for (idx_t k = 14; k <= n; ++k) {
        long long sum = 0;
        for (int j = 1; j < 14; ++j) {
            seq_t v = buf[(k - j) % 14];
            sum += coeff[j] * (long long)v;
        }
        buf[k % 14] = (seq_t)(-sum);
    }

    return buf[n % 14];
}
